import { stat } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const DATA_DIR = path.resolve(fileURLToPath(new URL('.', import.meta.url)), 'data');

const TOOLS = [
  {
    name: 'file_metadata',
    description:
      'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
    inputSchema: {
      type: 'object',
      properties: {
        path: {
          type: 'string',
          description: 'Path of the file relative to the data directory.',
        },
      },
      required: ['path'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }

  const { path: rel } = args;
  if (typeof rel !== 'string' || rel.length === 0) {
    throw new Error('path is required');
  }
  if (rel.indexOf('\0') !== -1) {
    throw new Error('Invalid path');
  }
  // Reject absolute paths and any traversal outside the data directory.
  if (path.isAbsolute(rel)) {
    throw new Error('Path must be relative to the data directory');
  }

  const resolved = path.resolve(DATA_DIR, rel);
  const relFromData = path.relative(DATA_DIR, resolved);
  if (relFromData === '' || relFromData.startsWith('..') || path.isAbsolute(relFromData)) {
    throw new Error('Path traversal is not allowed');
  }

  let stats;
  try {
    stats = await stat(resolved);
  } catch (error) {
    if (error && (error.code === 'ENOENT' || error.code === 'ENOTDIR')) {
      throw new Error('File not found: ' + rel);
    }
    throw error;
  }
  if (!stats.isFile()) {
    throw new Error('Not a file: ' + rel);
  }

  const ext = path.extname(relFromData).toLowerCase();
  const text = [
    'path: ' + relFromData,
    'size: ' + stats.size + ' bytes',
    'extension: ' + (ext || '(none)'),
  ].join('\n');

  return {
    content: [{ type: 'text', text }],
  };
}

